<script lang="ts">
  import { onMount } from 'svelte';
  import Icon from '#lib/Icon.svelte';
  import JobDetail from '#lib/JobDetail.svelte';
  import { api, message, refreshWorkspace } from '#lib/api';
  import type { Bootstrap, Job } from '#lib/types';
  let bootstrap: Bootstrap | null = null;
  let query = '';
  let mode = 'natural';
  let loading = false;
  let searched = false;
  let jobs: Job[] = [];
  let selected: Job | null = null;
  let error = '';
  let note = '';
  let warnings: string[] = [];
  let parsed: Record<string, unknown> | null = null;
  const examples = ['Java backend jobs in fintech', 'Jobs matching my resume posted this week', 'Internships at mid-size companies'];
  onMount(async () => { try { bootstrap = await api<Bootstrap>('/bootstrap'); if (!bootstrap.model_configured) mode='keyword'; } catch(e) {error=message(e);} });
  async function search() {
    if (!query.trim()) return;
    loading=true; error=''; selected=null;
    try {
      const result = await api<{jobs:Job[]; relaxation_note:string; warnings:string[]; query_spec:Record<string,unknown>}>('/search',{method:'POST',body:JSON.stringify({query,mode,limit:15})});
      jobs=result.jobs; note=result.relaxation_note; warnings=result.warnings; parsed=result.query_spec; searched=true; refreshWorkspace();
      if(jobs.length) selected=jobs[0];
    } catch(e){error=message(e);} finally {loading=false;}
  }
</script>
<div class="page-heading"><div><p class="eyebrow">A LITTLE MORE DIRECTION</p><h1>Find your next role.</h1><p>Technology jobs that make sense for your experience and your goals.</p></div><a class="button-link" href="/resume"><Icon name="upload" size={15}/>{bootstrap?.resume ? 'Your resume' : 'Add your resume'}</a></div>
<section class="search-panel panel" aria-label="Job search">
  <div class="row between"><span class="search-label"><Icon name="sparkle" size={15}/>What are you looking for?</span><div class="tabs" aria-label="Search mode"><button class:selected={mode==='natural'} onclick={() => mode='natural'}>Natural language</button><button class:selected={mode==='keyword'} onclick={() => mode='keyword'}>Keywords</button></div></div>
  <form onsubmit={(e) => {e.preventDefault();search();}}><label class="sr-only" for="job-query">Describe the jobs you want</label><textarea id="job-query" bind:value={query} placeholder={mode==='natural'?'For example, find Java backend roles at fintech companies that fit my projects…':'Enter technology and role keywords, e.g. Python backend engineer'} rows="2" maxlength="2000"></textarea><div class="search-footer"><span><Icon name="info" size={12}/>{mode==='natural'?'Required filters stay strict. Preferences shape your fit score.':'Technology and role keywords only. No model call.'}</span><button class="primary" type="submit" disabled={loading || !query.trim()}>{#if loading}<span class="spinner"></span>Searching…{:else}<Icon name="search" size={15}/>Find jobs{/if}</button></div></form>
  {#if mode==='natural'}<div class="examples"><span>Try a search</span>{#each examples as example}<button onclick={() => query=example}>{example}<Icon name="arrow" size={11}/></button>{/each}</div>{/if}
</section>
{#if bootstrap && !bootstrap.model_configured}<div class="notice section-gap"><Icon name="info" size={16}/><span>Keyword search is ready to use. <a href="/settings">Connect a free OpenRouter model</a> for natural-language search, resume facts, and research.</span></div>{/if}
{#if error}<div class="error section-gap" role="alert">{error}</div>{/if}
{#if loading}<div class="panel section-gap" role="status"><div class="loading-line"><span class="spinner"></span>Checking company career pages and ranking real postings…</div><p class="fine-print" style="margin-top:10px">Complex searches can take a minute. New results will be added to your tracker.</p></div>{/if}
<div class="results-heading"><div class="row"><h2>{searched?'Your matches':'A search with a clearer picture'}</h2>{#if searched}<span class="badge">{jobs.length} roles</span>{/if}</div>{#if searched && parsed}<details class="parsed"><summary>View interpreted query</summary><pre>{JSON.stringify(parsed,null,2)}</pre></details>{:else}<span class="meta">Worldwide · Technology · Your preferences</span>{/if}</div>
{#if searched && note}<p class="result-note">{note}</p>{/if}
{#if warnings.length}<details class="warnings"><summary>{warnings.length} source notice{warnings.length===1?'':'s'}</summary>{#each warnings as warning}<p>{warning}</p>{/each}</details>{/if}
{#if jobs.length}<div class="results-layout" class:with-detail={selected}><div class="job-list">{#each jobs as job}<button class="job-card" class:chosen={selected?.id===job.id} onclick={() => selected=job}><div class="row between"><div class="row"><span class="company-avatar">{job.company.slice(0,1)}</span><span class="company-label">{job.company}</span></div><span class="score" class:low={(job.fit_score || 0)<50}>{job.fit_score ?? '—'}<small>fit score</small></span></div><h3>{job.title}</h3><div class="meta"><span><Icon name="pin" size={12}/>{job.location}</span>{#if job.posted_at}<span><Icon name="clock" size={12}/>{new Date(job.posted_at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span>{/if}</div><p class="job-snippet">{job.description_snippet || job.snippet || 'Open the role to review its description.'}</p><div class="card-bottom"><span class="badge">{job.source==='ats'?'Direct ATS source':job.source==='playwright'?'Rendered career page':'Company career page'}</span><span>View role <Icon name="arrow" size={12}/></span></div></button>{/each}</div>{#if selected}<JobDetail job={selected} onclose={() => selected=null}/>{/if}</div>
{:else if searched}<div class="panel empty-state"><div class="empty-icon"><Icon name="search" size={28}/></div><h3>No new qualifying roles found</h3><p>Your hard filters are preserved, and roles already in your tracker are excluded. Adjust the query, add sources, or review saved jobs.</p><a class="button-link" href="/tracker">Open your tracker <Icon name="arrow" size={13}/></a></div>
{:else}<div class="welcome-grid"><div class="panel welcome-main"><span class="empty-icon"><Icon name="search" size={26}/></span><h3>A few words. A more focused search.</h3><p>Start with a role, a stack, or the kind of company you want to join. Add a resume when you want matches grounded in your experience.</p><div class="steps"><span><b>1</b>Find a role</span><span class="step-arrow">→</span><span><b>2</b>Prepare with care</span><span class="step-arrow">→</span><span><b>3</b>Track your progress</span></div></div><div class="panel welcome-side"><span class="badge blue">BUILT AROUND YOU</span><h3>Quality over volume.</h3><p>Materials are created for a single job when you ask. Claims are checked against your stored facts. You stay in control of every submission.</p><a class="text-link" href="/resume">Add your starting point <Icon name="arrow" size={13}/></a></div></div>{/if}
<style>
  .search-panel{padding:21px 24px}.search-label{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:600;color:#5b6c89}.search-label :global(svg){color:var(--blue)}form{margin-top:15px;border:1px solid #dfe5ef;border-radius:10px;overflow:hidden}textarea{width:100%;border:0;resize:vertical;min-height:82px;max-height:220px;padding:17px 18px;color:var(--ink);font-size:13px;line-height:1.8;background:white}textarea::placeholder{color:#a1adbf}textarea:focus{outline:0}.search-footer{padding:0 13px 13px;display:flex;align-items:center;justify-content:space-between;gap:10px}.search-footer>span{font-size:10px;color:#98a5b9;display:flex;align-items:center;gap:5px}.search-footer button{font-size:12px;padding:11px 17px}.examples{display:flex;align-items:center;gap:7px;margin-top:16px;flex-wrap:wrap}.examples>span{font-size:10px;color:#9aa5b7;margin-right:4px}.examples button{border-color:#edf0f5;color:#8190a8;font-size:9px;padding:6px 9px;font-weight:400;border-radius:5px}.results-heading{display:flex;align-items:center;justify-content:space-between;margin-top:32px;margin-bottom:18px;gap:15px}.results-heading h2{font-size:16px}.result-note{font-size:11px;color:#8b97a9;margin:-7px 0 17px;line-height:1.7}.results-layout{display:grid;grid-template-columns:1fr;gap:21px}.results-layout.with-detail{grid-template-columns:minmax(0,1.1fr) minmax(330px,.9fr)}.job-list{display:grid;gap:13px;align-content:start}.job-card{display:block;text-align:left;padding:20px;background:#fff;border-radius:11px;box-shadow:0 2px 3px #1c294003;font-weight:400;overflow:hidden}.job-card:hover:not(:disabled){background:white;border-color:#c9d8f5}.job-card.chosen{border-color:#92b4f9;box-shadow:0 0 0 1px #c7d8fa}.company-avatar{width:30px;height:30px;border-radius:8px;background:#f1f4fa;color:#647895;display:grid;place-items:center;font-size:14px;font-weight:600}.company-label{font-size:11px;color:#7f8ca1}.job-card h3{margin:13px 0 10px;font-size:15px;max-width:90%}.job-snippet{color:#92a0b4;font-size:11px;font-weight:400;line-height:1.8;margin-top:13px;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.card-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:17px;padding-top:13px;border-top:1px solid #f0f2f6}.card-bottom>span:last-child{display:flex;align-items:center;gap:5px;color:#7091c8;font-size:10px}.welcome-grid{display:grid;grid-template-columns:1.6fr 1fr;gap:22px}.welcome-main{padding:40px 30px}.welcome-main .empty-icon{margin:0 0 22px;width:49px;height:49px;border-radius:13px}.welcome-main h3{font-size:18px;letter-spacing:-.3px;margin-bottom:12px}.welcome-main>p{font-size:12px;color:#8592a8;max-width:450px}.steps{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:27px}.steps span{font-size:10px;color:#8391a8;display:inline-flex;align-items:center;gap:6px}.steps b{font-size:9px;width:19px;height:19px;display:grid;place-items:center;background:#f1f5fb;border-radius:50%;font-weight:500;color:#8ca2c5}.steps .step-arrow{color:#bbc7d9}.welcome-side{background:#f0f5ff;border-color:#e5ecfb;padding:32px 25px}.welcome-side h3{font-size:19px;margin:24px 0 13px;letter-spacing:-.4px}.welcome-side p{font-size:12px;color:#8496b4;line-height:1.85}.welcome-side>a{margin-top:25px;font-size:11px}.parsed{position:relative}.parsed summary{font-size:10px}.parsed pre{position:absolute;right:0;width:320px;max-height:350px;overflow:auto;background:white;z-index:5;border:1px solid var(--line);padding:16px;border-radius:8px;font-size:10px}.warnings{margin-bottom:15px}.warnings p{font-size:11px;color:#9a8871;margin-top:7px}@media(max-width:1050px){.results-layout.with-detail{grid-template-columns:minmax(0,1fr) minmax(300px,1fr)}}@media(max-width:900px){.results-layout.with-detail{grid-template-columns:1fr}.welcome-grid{grid-template-columns:1fr}.search-footer>span{max-width:220px}.results-layout.with-detail>.job-list{max-height:390px;overflow:auto}.page-heading>.button-link{font-size:10px;white-space:nowrap}.examples button{font-size:10px}}@media(max-width:700px){.search-panel{padding:17px}.search-panel>.row{align-items:flex-start;gap:12px;flex-direction:column}.search-footer>span{font-size:9px;max-width:150px}.search-footer button{padding:9px 11px;font-size:11px}.results-heading{align-items:flex-start}.results-heading>.meta{max-width:120px;font-size:9px;text-align:right}.welcome-main{padding:30px 24px}.page-heading{gap:10px}.page-heading>.button-link{padding:8px;max-width:110px}.steps{gap:9px}.steps .step-arrow{display:none}}
</style>
